// Bids sorted ascending, so the best bid sits at back()
void AddBid(std::vector<PriceLevel>& bids, Price price, Volume vol) {
    auto it = std::lower_bound(bids.begin(), bids.end(), price,
        [](const PriceLevel& lvl, Price p) { return lvl.price < p; });
    if (it != bids.end() && it->price == price) {
        it->total_volume += vol;          // hot: the level exists
    } else {
        bids.insert(it, {price, vol});    // cold: memmove the tail
    }
}

// the top level traded away:
bids.pop_back();                          // O(1): nothing shifts

using OrderIter = std::list<Order>::iterator;

struct Limit {
    Price            price;
    Volume           total_volume = 0;   // cached per level
    std::list<Order> orders;             // FIFO; front() = oldest
};

struct Book {
    std::map<Price, Limit>                 bids, asks;
    std::unordered_map<OrderId, OrderIter> order_map;   // id → node
};

void cancel(Book& b, OrderId id) {
    OrderIter oit = b.order_map.at(id);                 // O(1)
    auto& side = (oit->side == Side::Bid) ? b.bids : b.asks;
    Limit& lmt = side.at(oit->price);                   // O(log N)
    lmt.total_volume -= oit->volume;
    Price price = oit->price;
    lmt.orders.erase(oit);                              // O(1) unlink
    if (lmt.orders.empty()) side.erase(price);          // level gone
    b.order_map.erase(id);
}
